function matMul(A, B, mod=0) {
  const n=A.length;
  const C=Array.from({length:n},()=>new Array(n).fill(0));
  for (let i=0;i<n;i++)
    for (let k=0;k<n;k++)
      if (A[i][k]!==0)
        for (let j=0;j<n;j++) {
          C[i][j]+=A[i][k]*B[k][j];
          if (mod) C[i][j]%=mod;
        }
  return C;
}

function identity(n) {
  return Array.from({length:n},(_,i)=>Array.from({length:n},(_,j)=>i===j?1:0));
}

function matPow(M, k, mod=0) {
  let result=identity(M.length);
  let base=M.map(r=>[...r]);
  while (k>0) {
    if (k&1) result=matMul(result,base,mod);
    base=matMul(base,base,mod);
    k>>=1;
  }
  return result;
}

function fib(n) {
  if (n<=1) return n;
  const T=[[1,1],[1,0]];
  return matPow(T,n-1)[0][0];
}

function rotate(matrix) {
  const n=matrix.length;
  for (let i=0;i<n;i++)
    for (let j=i+1;j<n;j++)
      [matrix[i][j],matrix[j][i]]=[matrix[j][i],matrix[i][j]];
  for (let i=0;i<n;i++) matrix[i].reverse();
}
